def _authenticate_pinned_sources(
    expected: Mapping[Path, str],
) -> dict[str, str]:
    """Hash an exact evidence allowlist and reject missing, linked, or changed files."""

    observed: dict[str, str] = {}
    for path, expected_sha256 in expected.items():
        absolute = _absolute(path)
        if not absolute.is_file() or absolute.is_symlink():
            raise FileNotFoundError(f"Pinned evidence file is absent or linked: {path}")
        digest = _sha256_file(path)
        if digest != expected_sha256:
            raise ValueError(
                f"Pinned evidence digest changed for {path}: {digest} != {expected_sha256}"
            )
        observed[path.as_posix()] = digest
    return observed


def _inspect_fixed_prefix_atlas_v2() -> dict[str, Any]:
    """Authenticate Atlas V2 as structural exposure evidence, never behavior."""

    evidence_paths = [path.as_posix() for path in FIXED_ATLAS_V2_SOURCE_SHA256]
    try:
        source_hashes = _authenticate_pinned_sources(FIXED_ATLAS_V2_SOURCE_SHA256)
        config = yaml.safe_load(_absolute(FIXED_ATLAS_V2_CONFIG).read_text(encoding="utf-8"))
        if not isinstance(config, Mapping):
            raise TypeError("Atlas V2 config is not a mapping")
        atlas = config.get("strict_fixed_prefix_atlas")
        exposure = config.get("sliding_attention_exposure")
        evaluation = config.get("evaluation")
        if not all(isinstance(value, Mapping) for value in (atlas, exposure, evaluation)):
            raise TypeError("Atlas V2 config sections are incomplete")

        expected_layout = [
            "boi",
            "all_atlas_key_value_tokens",
            "all_base_scene_latents",
            "eoi",
        ]
        config_checks = {
            "architecture_exact": atlas.get("architecture") == "fixed_scene_key_value_atlas_v2",
            "status_structural_only": atlas.get("status")
            == "structural_layout_only_waiting_for_accepted_sealed_controller",
            "compilation_disabled": atlas.get("compilation_enabled") is False,
            "sealed_controller_absent": atlas.get("source_sealed_controller") is None,
            "output_checkpoint_absent": atlas.get("output_checkpoint") is None,
            "complete_layout_exact": atlas.get("layout") == expected_layout,
            "fixed_prefix_count_exact": atlas.get("compiled_fixed_prefix_tokens") == 738,
            "base_latent_count_exact": atlas.get("base_environment_latents") == 256,
            "atlas_memory_count_exact": atlas.get("atlas_memory_tokens") == 480,
            "compiled_before_question": atlas.get("compile_before_user_question") is True,
            "question_processing_absent": (
                atlas.get("question_dependent_scene_processing") is False
                and atlas.get("question_dependent_retrieval") is False
                and atlas.get("semantic_or_spatial_top_k_selection") is False
            ),
            "environmental_text_inputs_empty": atlas.get("runtime_environmental_text_inputs") == [],
            "sliding_window_exact": exposure.get("sliding_window_tokens") == 512,
            "prompt_range_exact": exposure.get("prompt_token_range_including_bos") == [57, 64],
            "config_v1_visibility_zero": exposure.get("final_prompt_token_v1_visible_base_latents")
            == 0,
            "config_v2_visibility_complete": exposure.get(
                "final_prompt_token_v2_visible_base_latents"
            )
            == 256,
            "behavior_unmeasured": evaluation.get("behavioral_accuracy_measured") is False,
            "behavioral_improvement_unclaimed": evaluation.get("behavioral_improvement_claimed")
            is False,
        }
        if not all(config_checks.values()):
            failed = sorted(key for key, passed in config_checks.items() if not passed)
            raise ValueError(f"Atlas V2 config contract failed: {failed}")

        from semantic_3d_chat.evaluation.fixed_prefix_atlas_v2_exposure import (
            gemma4_e2b_prompt_exposure_table,
        )

        table = gemma4_e2b_prompt_exposure_table()
        exposure_rows = []
        for v1, v2 in table:
            if (
                v1.prompt_token_count_including_bos != v2.prompt_token_count_including_bos
                or v1.visible_base_latent_count != 0
                or v2.visible_base_latent_count != 256
                or v1.total_base_latent_count != 256
                or v2.total_base_latent_count != 256
                or v2.total_atlas_token_count != 480
                or v1.sliding_window != 512
                or v2.sliding_window != 512
                or v1.attention_layer_kind != "sliding_attention"
                or v2.attention_layer_kind != "sliding_attention"
            ):
                raise ValueError("Atlas V2 computed exposure differs from its pinned contract")
            exposure_rows.append(
                {
                    "prompt_tokens_including_bos": v2.prompt_token_count_including_bos,
                    "final_prompt_query_position": v2.final_prompt_query_position,
                    "first_visible_key_position": v2.first_visible_key_position,
                    "v1_visible_base_latents": v1.visible_base_latent_count,
                    "v2_visible_base_latents": v2.visible_base_latent_count,
                    "v2_visible_atlas_tokens": v2.visible_atlas_token_count,
                }
            )
        if [row["prompt_tokens_including_bos"] for row in exposure_rows] != list(range(57, 65)):
            raise ValueError("Atlas V2 exposure table does not cover prompts 57 through 64")

        return {
            "status": "authenticated_structural_only_compilation_disabled",
            "evidence_authenticated": True,
            "architecture": "fixed_scene_key_value_atlas_v2",
            "fixed_prefix_token_count": 738,
            "base_scene_latent_count": 256,
            "atlas_memory_token_count": 480,
            "layout": expected_layout,
            "compiled_before_user_question": True,
            "question_dependent_scene_processing": False,
            "question_dependent_retrieval": False,
            "environmental_text_inputs": [],
            "compilation_enabled": False,
            "accepted_sealed_controller_present": False,
            "checkpoint_present": False,
            "behavioral_accuracy_measured": False,
            "behavioral_improvement_claimed": False,
            "direct_sliding_attention_exposure_only": True,
            "periodic_full_attention_layers_outside_calculation": True,
            "sliding_window_tokens": 512,
            "prompt_token_range_including_bos": [57, 64],
            "v1_visible_base_latents": 0,
            "v2_visible_base_latents": 256,
            "exposure_rows": exposure_rows,
            "config_checks": config_checks,
            "implementation_source_sha256": source_hashes,
            "measurement_evidence_paths": evidence_paths,
            "scope_warning": (
                "Lossless layout and direct local-window exposure only; compilation, "
                "generation, behavioral scoring, and improvement claims remain disabled."
            ),
        }
    except (ImportError, KeyError, TypeError, ValueError, FileNotFoundError) as error:
        return {
            "status": "structural_evidence_authentication_failed",
            "evidence_authenticated": False,
            "compilation_enabled": False,
            "behavioral_accuracy_measured": False,
            "behavioral_improvement_claimed": False,
            "measurement_evidence_error": f"{type(error).__name__}: {error}",
            "measurement_evidence_paths": evidence_paths,
        }


def _inspect_ple_reader_preregistration() -> dict[str, Any]:
    """Authenticate the design-only PLE reader contract without authorizing training."""

    evidence_paths = [path.as_posix() for path in PLE_READER_SOURCE_SHA256]
    try:
        source_hashes = _authenticate_pinned_sources(PLE_READER_SOURCE_SHA256)
        artifact = _read_object(PLE_READER_PREREGISTRATION)
        config = yaml.safe_load(_absolute(PLE_READER_CONFIG).read_text(encoding="utf-8"))
        if not isinstance(config, Mapping):
            raise TypeError("PLE reader config is not a mapping")

        from semantic_3d_chat.evaluation.ple_reader_preregistration import (
            LORA_PARAMETER_COUNT,
            build_ple_reader_preregistration,
        )

        if artifact != build_ple_reader_preregistration():
            raise ValueError("PLE reader preregistration JSON differs from its pinned source")
        experiment = config.get("experiment")
        if not isinstance(experiment, Mapping):
            raise TypeError("PLE reader experiment config is incomplete")
        execution = artifact.get("execution")
        surface = artifact.get("trainable_surface")
        authorization = artifact.get("atlas_v2_launch_authorization")
        runtime = artifact.get("runtime_and_leakage")
        if not all(
            isinstance(value, Mapping) for value in (execution, surface, authorization, runtime)
        ):
            raise TypeError("PLE reader preregistration sections are incomplete")
        checks = {
            "status_design_only": artifact.get("status") == "design_locked_training_not_authorized",
            "config_status_matches": experiment.get("status")
            == "design_locked_training_not_authorized",
            "model_exact": experiment.get("model_id") == "google/gemma-4-E2B-it",
            "target_exact": experiment.get("target_module")
            == "model.language_model.per_layer_model_projection",
            "rank_exact": surface.get("rank") == experiment.get("rank") == 4,
            "parameter_count_exact": (
                surface.get("parameter_count")
                == experiment.get("trainable_parameter_count")
                == LORA_PARAMETER_COUNT
                == 41_984
            ),
            "atlas_acceptance_required": authorization.get(
                "atlas_v2_must_be_accepted_before_training"
            )
            is True,
            "concrete_hashes_required_at_launch": (
                authorization.get("all_digest_values_required_at_launch") is True
                and authorization.get("digest_placeholders_permitted") is False
            ),
            "training_not_executed": execution.get("training_executed") is False,
            "generation_not_executed": execution.get("gemma_generation_executed") is False,
            "checkpoint_not_published": execution.get("checkpoint_published") is False,
            "environmental_text_inputs_empty": runtime.get("environmental_text_inputs") == [],
            "question_independent_prefix_required": authorization.get(
                "reuse_identical_prefix_for_every_unchanged_scene_question"
            )
            is True,
        }
        if not all(checks.values()):
            failed = sorted(key for key, passed in checks.items() if not passed)
            raise ValueError(f"PLE reader preregistration contract failed: {failed}")

        return {
            "status": "authenticated_design_only_training_not_authorized",
            "evidence_authenticated": True,
            "design_only": True,
            "training_authorized": False,
            "training_executed": False,
            "gemma_generation_executed": False,
            "checkpoint_published": False,
            "behavioral_accuracy_measured": False,
            "model_id": "google/gemma-4-E2B-it",
            "target_module": "model.language_model.per_layer_model_projection",
            "projection_shape": [8960, 1536],
            "rank": 4,
            "alpha": 8.0,
            "trainable_parameter_count": 41_984,
            "atlas_v2_acceptance_required_before_training": True,
            "question_independent_prefix_required": True,
            "environmental_text_inputs": [],
            "checks": checks,
            "preregistration_sha256": source_hashes[PLE_READER_PREREGISTRATION.as_posix()],
            "implementation_source_sha256": source_hashes,
            "measurement_evidence_paths": evidence_paths,
            "scope_warning": (
                "Preregistered design only: no accepted Atlas V2 artifact exists, "
                "so training, generation, checkpoint publication, and behavioral "
                "claims are unauthorized."
            ),
        }
    except (ImportError, KeyError, TypeError, ValueError, FileNotFoundError) as error:
        return {
            "status": "preregistration_evidence_authentication_failed",
            "evidence_authenticated": False,
            "design_only": True,
            "training_authorized": False,
            "training_executed": False,
            "behavioral_accuracy_measured": False,
            "measurement_evidence_error": f"{type(error).__name__}: {error}",
            "measurement_evidence_paths": evidence_paths,
        }


