def _inspect_embodied_hybrid_approach_v2() -> dict[str, Any]:
    """Authenticate the preserved two-scene V2 approach development result."""

    evidence_paths = [
        *(path.as_posix() for path in EMBODIED_HYBRID_APPROACH_V2_EVIDENCE_SHA256),
        *(path.as_posix() for path in EMBODIED_HYBRID_APPROACH_V2_SOURCE_PATHS),
    ]
    try:
        for path, expected_sha256 in EMBODIED_HYBRID_APPROACH_V2_EVIDENCE_SHA256.items():
            resolved = _absolute(path)
            if not resolved.is_file() or resolved.is_symlink():
                raise FileNotFoundError(f"V2 approach evidence is missing or unsafe: {path}")
            if _sha256_file(path) != expected_sha256:
                raise ValueError(f"V2 approach evidence digest differs: {path}")

        score = _read_object(EMBODIED_HYBRID_APPROACH_V2_SCORE)
        results = [_read_object(path) for path in EMBODIED_HYBRID_APPROACH_V2_RESULTS]
        score_rows = score.get("scenes")
        if not isinstance(score_rows, list) or len(score_rows) != 2:
            raise TypeError("V2 approach oracle score must contain exactly two scenes")
        if not (
            score.get("schema") == "semantic_3d_chat.embodied_approach_oracle_score.v1"
            and score.get("status") == "evaluation_only_oracle_score"
            and score.get("scorer_reads_oracle") is True
            and score.get("runtime_process_read_oracle") is False
            and score.get("runtime_evidence_validated_before_oracle_open") is True
            and score.get("runtime_environmental_text_inputs") == []
            and score.get("target_category_used_only_by_scorer") == "chair"
            and score.get("minimum_center_progress_m") == 0.25
            and score.get("maximum_bbox_standoff_m") == 0.6
            and score.get("scene_count") == 2
            and score.get("passed_count") == 1
            and score.get("all_passed") is False
        ):
            raise ValueError("V2 approach score scope or aggregate differs")

        expected = (
            {
                "scene_id": "scene_000001",
                "passed": True,
                "runtime_completed": True,
                "stopped": True,
                "collision": False,
                "termination_reason": "stop",
                "numeric_translation_m": 0.7003040825966198,
                "oracle_center_progress_m": 0.6931714397860462,
                "final_oracle_bbox_standoff_m": 0.35259142696607015,
            },
            {
                "scene_id": "scene_000031",
                "passed": False,
                "runtime_completed": False,
                "stopped": False,
                "collision": True,
                "termination_reason": "action_failure",
                "numeric_translation_m": 1.2202412709593775,
                "oracle_center_progress_m": 1.2077359234198912,
                "final_oracle_bbox_standoff_m": 0.358838234313414,
            },
        )
        sanitized_runs: list[dict[str, Any]] = []
        for result, score_row, result_path, expected_row in zip(
            results,
            score_rows,
            EMBODIED_HYBRID_APPROACH_V2_RESULTS,
            expected,
            strict=True,
        ):
            if not isinstance(score_row, Mapping):
                raise TypeError("V2 approach score row is not a mapping")
            startup = result.get("startup")
            turns = result.get("turns")
            if not isinstance(startup, Mapping) or not isinstance(turns, list) or len(turns) != 1:
                raise TypeError(f"V2 approach runtime structure differs: {result_path}")
            navigation_policy = startup.get("navigation_policy")
            turn = turns[0]
            if not isinstance(navigation_policy, Mapping) or not isinstance(turn, Mapping):
                raise TypeError(f"V2 approach runtime policy differs: {result_path}")
            interlock = navigation_policy.get("numeric_alignment_convergence_interlock")
            receipts = turn.get("action_receipts")
            groundings = turn.get("continuous_grounding_attestations")
            if (
                not isinstance(interlock, Mapping)
                or not isinstance(receipts, list)
                or len(receipts) != 6
                or not isinstance(groundings, list)
                or len(groundings) != 6
            ):
                raise TypeError(f"V2 approach runtime action evidence differs: {result_path}")
            final_receipt = receipts[-1]
            if not isinstance(final_receipt, Mapping):
                raise TypeError(f"V2 approach final receipt differs: {result_path}")

            resolved_score_path = Path(str(score_row.get("result_path"))).resolve()
            runtime_ok = (
                result.get("schema") == "semantic_3d_chat.embodied_conversation_result.v1"
                and result.get("scene_id") == expected_row["scene_id"]
                and result.get("passed_runtime_audit") is True
                and result.get("forbidden_access_count") == 0
                and result.get("environmental_text_inputs") == []
                and navigation_policy.get("complete_scene_prefix_required") is True
                and navigation_policy.get("continuous_semantic_grounding") is True
                and navigation_policy.get("all_map_voxels_scored_for_grounding") is True
                and navigation_policy.get("every_scene_token_processed") is True
                and navigation_policy.get("oracle_inputs_at_runtime") is False
                and navigation_policy.get("environmental_text_inputs") == []
                and interlock.get("oracle_inputs_at_runtime") is False
                and interlock.get("environmental_text_inputs") == []
                and turn.get("success") is expected_row["runtime_completed"]
                and turn.get("termination_reason") == expected_row["termination_reason"]
                and turn.get("step_count") == 6
                and turn.get("prefix_refresh_verified") is True
                and turn.get("static_scene_prefix_question_independent") is True
                and turn.get("primary_static_scene_retrieval") is False
                and turn.get("question_dependent_navigation_grounding") is True
                and turn.get("environmental_text_inputs") == []
                and all(
                    isinstance(row, Mapping)
                    and row.get("all_map_voxels_scored") is True
                    and row.get("oracle_inputs_at_runtime") is False
                    and row.get("environmental_text_inputs") == []
                    for row in groundings
                )
                and final_receipt.get("collision") is expected_row["collision"]
                and final_receipt.get("stopped") is expected_row["stopped"]
            )
            score_ok = (
                score_row.get("scene_id") == expected_row["scene_id"]
                and score_row.get("passed") is expected_row["passed"]
                and score_row.get("runtime_completed") is expected_row["runtime_completed"]
                and score_row.get("stopped") is expected_row["stopped"]
                and score_row.get("collision") is expected_row["collision"]
                and score_row.get("termination_reason") == expected_row["termination_reason"]
                and score_row.get("step_count") == 6
                and score_row.get("runtime_environmental_text_inputs") == []
                and score_row.get("runtime_forbidden_access_count") == 0
                and resolved_score_path == _absolute(result_path).resolve()
                and score_row.get("result_sha256")
                == EMBODIED_HYBRID_APPROACH_V2_EVIDENCE_SHA256[result_path]
                and score_row.get("numeric_translation_m") == expected_row["numeric_translation_m"]
                and score_row.get("oracle_center_progress_m")
                == expected_row["oracle_center_progress_m"]
                and score_row.get("final_oracle_bbox_standoff_m")
                == expected_row["final_oracle_bbox_standoff_m"]
            )
            if not runtime_ok or not score_ok:
                raise ValueError(
                    f"V2 approach runtime or evaluator result differs: {expected_row['scene_id']}"
                )
            sanitized_runs.append(dict(expected_row))

        return {
            "status": "authenticated_two_scene_v2_approach_development_one_of_two_passed",
            "evidence_authenticated": True,
            "development_only": True,
            "official_validation": False,
            "runtime_promotion_authorized": False,
            "scene_count": 2,
            "passed_count": 1,
            "all_passed": False,
            "runtime_oracle_inputs": False,
            "runtime_environmental_text_inputs": [],
            "runtime_forbidden_access_count": 0,
            "oracle_scorer_evaluation_only": True,
            "oracle_files_opened_by_report_builder": False,
            "minimum_center_progress_m": 0.25,
            "maximum_bbox_standoff_m": 0.6,
            "runs": sanitized_runs,
            "score_sha256": EMBODIED_HYBRID_APPROACH_V2_EVIDENCE_SHA256[
                EMBODIED_HYBRID_APPROACH_V2_SCORE
            ],
            "measurement_evidence_paths": evidence_paths,
            "measurement_evidence_sha256": {
                path: _sha256_file(Path(path)) for path in evidence_paths
            },
            "scope_warning": (
                "Preserved two-scene V2 approach development result only: one pass "
                "and one collision failure. Runtime used continuous semantics and numeric "
                "state without oracle or environmental-text inputs; target identity and "
                "oracle geometry were opened only by the physically separate evaluator. "
                "This result is not promoted or held-out navigation evidence."
            ),
        }
    except (KeyError, TypeError, ValueError, FileNotFoundError, OSError) as error:
        return {
            "status": "artifact_present_authentication_failed",
            "evidence_authenticated": False,
            "runtime_promotion_authorized": False,
            "official_validation": False,
            "measurement_evidence_error": f"{type(error).__name__}: {error}",
            "measurement_evidence_paths": evidence_paths,
        }


