def _inspect_v94_strong_causal_ablations() -> dict[str, Any]:
    """Authenticate and sanitize the terminal post-hoc V94 causal controls."""

    path = V94_STRONG_CAUSAL_ABLATIONS
    evidence_path = path.as_posix()
    try:
        resolved = _absolute(path)
        if not resolved.is_file() or resolved.is_symlink():
            raise FileNotFoundError(f"V94 strong-causal report is missing or unsafe: {path}")
        digest = _sha256_file(path)
        if digest != V94_STRONG_CAUSAL_ABLATIONS_SHA256:
            raise ValueError("V94 strong-causal report digest differs")
        report = _read_object(path)
        metrics = report.get("metrics")
        arms = metrics.get("arms") if isinstance(metrics, Mapping) else None
        comparisons = metrics.get("comparisons") if isinstance(metrics, Mapping) else None
        channels = report.get("channel_identifiability")
        if not isinstance(arms, Mapping) or not isinstance(comparisons, Mapping):
            raise TypeError("V94 strong-causal metrics are malformed")
        if not isinstance(channels, Mapping):
            raise TypeError("V94 strong-causal channel inventory is malformed")

        expected_conditions = [
            "primary",
            "zero_full_scene",
            "wrong_scene_swap",
            "full_interior_token_permutation",
            "position_spatial_shuffle",
            "remove_rgb",
            "semantic_payload_shuffle",
        ]
        expected_correct = {
            "primary": 143,
            "zero_full_scene": 85,
            "wrong_scene_swap": 140,
            "full_interior_token_permutation": 143,
            "position_spatial_shuffle": 132,
            "remove_rgb": 147,
            "semantic_payload_shuffle": 131,
        }
        expected_changes = {
            "zero_full_scene": 138,
            "wrong_scene_swap": 30,
            "full_interior_token_permutation": 57,
            "position_spatial_shuffle": 72,
            "remove_rgb": 8,
            "semantic_payload_shuffle": 73,
        }
        exact_scope = (
            report.get("artifact") == "v94_strong_causal_label_isolated_score_v1"
            and report.get("status")
            == "terminal_measured_posthoc_diagnostic_non_promotable"
            and report.get("evaluation_profile") == "full"
            and report.get("scene_count") == 6
            and report.get("row_count") == 216
            and report.get("conditions") == expected_conditions
            and report.get("terminal_diagnostic_only") is True
            and report.get("runtime_promotion_authorized") is False
            and report.get("automatic_runtime_promotion") is False
            and report.get("answers_questions_or_oracle_serialized") is False
            and report.get("labels_opened_only_by_separate_scorer") is True
            and report.get("prediction_bundle_authenticated_before_labels_opened") is True
            and report.get("scorer_loaded_model") is False
        )
        exact_arms = all(
            isinstance(arms.get(name), Mapping)
            and arms[name].get("correct") == correct
            and arms[name].get("total") == 216
            for name, correct in expected_correct.items()
        )
        exact_changes = all(
            isinstance(comparisons.get(name), Mapping)
            and comparisons[name].get("prediction_change_count") == changed
            for name, changed in expected_changes.items()
        )
        unsupported_channels_honest = (
            channels.get("normal", {}).get("observed_nonzero_value_count_across_six_scenes")
            == 0
            and channels.get("normal", {}).get("included_control") is None
            and channels.get("viewpoint", {}).get("included_control") is None
            and channels.get("viewpoint", {}).get(
                "independently_identifiable_before_scene_tokenization"
            )
            is False
        )
        if not exact_scope or not exact_arms or not exact_changes or not unsupported_channels_honest:
            raise ValueError("V94 strong-causal aggregate or claim scope differs")

        sanitized_arms = {
            name: {
                "correct": int(arms[name]["correct"]),
                "total": int(arms[name]["total"]),
                "accuracy": float(arms[name]["accuracy"]),
                "by_answer_type": arms[name]["by_answer_type"],
            }
            for name in expected_conditions
        }
        sanitized_comparisons = {
            name: {
                "accuracy_drop_from_primary": float(
                    comparisons[name]["accuracy_drop_from_primary"]
                ),
                "prediction_change_count": int(comparisons[name]["prediction_change_count"]),
                "prediction_change_rate": float(comparisons[name]["prediction_change_rate"]),
            }
            for name in expected_changes
        }
        return {
            "status": report["status"],
            "evidence_authenticated": True,
            "evaluation_profile": "full",
            "posthoc_non_preregistered": True,
            "terminal_diagnostic_only": True,
            "runtime_promotion_authorized": False,
            "held_out_or_generalization_claim": False,
            "official_or_final_evaluation_claim": False,
            "scene_count": 6,
            "question_count": 216,
            "answers_questions_or_oracle_serialized": False,
            "labels_opened_only_by_separate_scorer": True,
            "prediction_bundle_authenticated_before_labels_opened": True,
            "arms": sanitized_arms,
            "comparisons": sanitized_comparisons,
            "unsupported_controls": {
                "remove_normals": "all six sealed map normal tensors were already zero",
                "remove_viewpoint": "view direction is not consumed by the point tokenizer",
            },
            "nll_measured": False,
            "prediction_sha256": report["prediction_sha256"],
            "evidence_path": evidence_path,
            "evidence_sha256": digest,
            "scope_warning": (
                "Six-scene post-hoc diagnostic only. The zero-scene result shows real "
                "scene dependence, but wrong-scene and token-permutation controls show "
                "weak exact scene/order binding. It cannot authorize V94 release or "
                "support a held-out, generalization, official, or final-acceptance claim."
            ),
        }
    except (KeyError, TypeError, ValueError, FileNotFoundError, OSError) as error:
        return {
            "status": "artifact_present_authentication_failed",
            "evidence_authenticated": False,
            "runtime_promotion_authorized": False,
            "held_out_or_generalization_claim": False,
            "measurement_evidence_error": f"{type(error).__name__}: {error}",
            "measurement_evidence_paths": [evidence_path],
        }


