def _inspect_navigation_policy_v3_3_development_calibration() -> dict[str, Any]:
    """Authenticate the accepted, single-scene V3.3 development calibration."""

    evidence_paths = [path.as_posix() for path in NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256]
    try:
        for path, expected_sha256 in NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256.items():
            resolved = _absolute(path)
            if not resolved.is_file() or resolved.is_symlink():
                raise FileNotFoundError(f"V3.3 evidence is missing or unsafe: {path}")
            if _sha256_file(path) != expected_sha256:
                raise ValueError(f"V3.3 evidence digest differs: {path}")

        preregistration = _read_object(NAVIGATION_POLICY_V3_3_PREREGISTRATION)
        acceptance = _read_object(NAVIGATION_POLICY_V3_3_ACCEPTANCE)
        score = _read_object(NAVIGATION_POLICY_V3_3_SCORE)
        context = _read_object(NAVIGATION_POLICY_V3_3_CONTEXT)
        access = _read_object(NAVIGATION_POLICY_V3_3_ACCESS)
        metrics = score.get("metrics")
        tasks = score.get("tasks")
        context_metrics = context.get("metrics")
        gates = acceptance.get("gates")
        claim_scope = acceptance.get("claim_scope")
        if not isinstance(metrics, Mapping) or not isinstance(tasks, list):
            raise TypeError("V3.3 score is malformed")
        if not isinstance(context_metrics, Mapping) or not isinstance(gates, Mapping):
            raise TypeError("V3.3 context or gate evidence is malformed")
        if not isinstance(claim_scope, Mapping):
            raise TypeError("V3.3 claim scope is malformed")

        expected_families = {
            "nav_000": "face",
            "nav_001": "approach",
            "nav_002": "stop",
            "nav_003": "obstacle",
            "nav_004": "left_right",
            "nav_005": "update_after_scan",
        }
        by_id = {
            str(row.get("task_id")): row for row in tasks if isinstance(row, Mapping)
        }
        task_scope_ok = set(by_id) == set(expected_families) and all(
            by_id[task_id].get("family") == family
            and by_id[task_id].get("passed") is True
            for task_id, family in expected_families.items()
        )
        acceptance_hashes = acceptance.get("evidence_hashes")
        expected_bound_hashes = {
            NAVIGATION_POLICY_V3_3_ACCESS.as_posix(): NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                NAVIGATION_POLICY_V3_3_ACCESS
            ],
            NAVIGATION_POLICY_V3_3_SCORE.as_posix(): NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                NAVIGATION_POLICY_V3_3_SCORE
            ],
            NAVIGATION_POLICY_V3_3_CONTEXT.as_posix(): NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                NAVIGATION_POLICY_V3_3_CONTEXT
            ],
            NAVIGATION_POLICY_V3_3_JOURNAL.as_posix(): NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                NAVIGATION_POLICY_V3_3_JOURNAL
            ],
        }
        exact_scope = (
            preregistration.get("schema")
            == "semantic_3d_chat.navigation_policy_v3_3_preregistration.v1"
            and preregistration.get("status") == "sealed_before_single_v3_3_development_run"
            and acceptance.get("schema")
            == "semantic_3d_chat.navigation_policy_v3_3_result.v1"
            and acceptance.get("status") == "accepted_development_calibration"
            and acceptance.get("passed") is True
            and acceptance.get("runtime_version") == "v3.3"
            and acceptance.get("preregistration_sha256")
            == NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                NAVIGATION_POLICY_V3_3_PREREGISTRATION
            ]
            and acceptance_hashes == expected_bound_hashes
            and all(value is True for value in gates.values())
            and metrics.get("task_count") == 6
            and metrics.get("success_count") == 6
            and metrics.get("success_rate") == 1.0
            and metrics.get("executed_action_count") == 28
            and metrics.get("collision_count") == 0
            and metrics.get("action_failure_count") == 0
            and metrics.get("policy_rejection_count") == 0
            and score.get("claimed_trained_navigation_policy") is True
            and score.get("policy_status")
            == "supervised_continuous_semantic_grounded_navigation_policy_v3"
            and score.get("passed") is True
            and task_scope_ok
            and context.get("passed") is True
            and context.get("oracle_files_opened") == 0
            and context.get("qa_files_opened") == 0
            and context_metrics.get("passed") is True
            and context_metrics.get("step_count") == 28
            and context_metrics.get("decision_context_match_count") == 28
            and context_metrics.get("prefix_chain_match_count") == 28
            and context_metrics.get("robot_token_refresh_count") == 28
            and context_metrics.get("scene_prefix_refresh_count") == 1
            and context_metrics.get("map_update_count") == 1
            and context_metrics.get("environmental_text_inputs") == []
            and context_metrics.get("oracle_inputs_used") is False
            and access.get("forbidden_accesses") == []
            and claim_scope.get("development_calibration") is True
            and claim_scope.get("held_out_claim") is False
            and claim_scope.get("generalization_claim") is False
            and claim_scope.get("same_benchmark_used_for_diagnosis") is True
        )
        calibrated = by_id.get("nav_005", {})
        calibrated_metrics = calibrated.get("metrics")
        calibrated_checks = calibrated.get("checks")
        if not isinstance(calibrated_metrics, Mapping) or not isinstance(
            calibrated_checks, Mapping
        ):
            raise TypeError("V3.3 calibration task is malformed")
        calibration_ok = (
            all(value is True for value in calibrated_checks.values())
            and calibrated_metrics.get("executed_action_count") == 9
            and calibrated_metrics.get("successful_scan_count") == 1
            and calibrated_metrics.get("final_target_standoff_m")
            == 0.28686400627712905
            and calibrated_metrics.get("target_progress_m") == 2.1144650214101115
            and acceptance.get("calibration_task_calls")
            == ["scan", "move_to", "move_to", "move_to", "move_to", "move_to", "move_to", "move_to", "stop"]
        )
        if not exact_scope or not calibration_ok:
            raise ValueError("V3.3 aggregate, calibration, or claim scope differs")

        task_summaries = [
            {
                "task_id": task_id,
                "family": expected_families[task_id],
                "passed": True,
                "checks": dict(by_id[task_id]["checks"]),
                "metrics": dict(by_id[task_id]["metrics"]),
                "episode_sha256": by_id[task_id]["episode_sha256"],
            }
            for task_id in expected_families
        ]
        return {
            "status": "accepted_development_calibration",
            "evidence_authenticated": True,
            "runtime_version": "v3.3",
            "scene_id": "scene_000001",
            "scene_count": 1,
            "development_calibration": True,
            "same_benchmark_used_for_diagnosis": True,
            "held_out_claim": False,
            "generalization_claim": False,
            "project_wide_runtime_promotion_claimed": False,
            "runtime_variant_authorized_for_development_benchmark": True,
            "claimed_trained_navigation_policy": True,
            "policy_status": score["policy_status"],
            "metrics": dict(metrics),
            "by_family": score["by_family"],
            "tasks": task_summaries,
            "continuous_context": dict(context_metrics),
            "environmental_text_inputs": [],
            "oracle_inputs_at_runtime": False,
            "forbidden_runtime_access_count": 0,
            "calibration_task_id": "nav_005",
            "calibration_task_calls": list(acceptance["calibration_task_calls"]),
            "calibration_task_metrics": dict(calibrated_metrics),
            "trajectory_journal": {
                "path": NAVIGATION_POLICY_V3_3_JOURNAL.as_posix(),
                "sha256": NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256[
                    NAVIGATION_POLICY_V3_3_JOURNAL
                ],
            },
            "evidence_paths": evidence_paths,
            "evidence_sha256": {
                path.as_posix(): digest
                for path, digest in NAVIGATION_POLICY_V3_3_EVIDENCE_SHA256.items()
            },
            "scope_warning": (
                "Accepted correction/calibration on the same six-task, one-scene "
                "development benchmark used for diagnosis. It is not held-out or "
                "cross-scene generalization evidence. The supervised V3 controller "
                "is combined with the deterministic V3.3 numeric waypoint planner; "
                "this is not native Gemma JSON function calling."
            ),
        }
    except (KeyError, TypeError, ValueError, FileNotFoundError, OSError) as error:
        return {
            "status": "artifact_present_authentication_failed",
            "evidence_authenticated": False,
            "runtime_variant_authorized_for_development_benchmark": False,
            "held_out_claim": False,
            "generalization_claim": False,
            "measurement_evidence_error": f"{type(error).__name__}: {error}",
            "evidence_paths": evidence_paths,
        }


def build_summary() -> dict[str, Any]:
    machine = _read_object(MACHINE_REPORT)
    geometry = _read_object(GEOMETRY_REPORT)
    map_report = _read_object(MAP_REPORT)
    v55 = _read_object(V55_REPORT)
    direct = _inspect_direct_multiview_baseline()
    embodied = _read_object(EMBODIED_SMOKE)
    navigation = _read_object(SEMANTIC_NAVIGATION)
    robot_state = _read_object(ROBOT_STATE_REPORT)
    tests = _read_object(TEST_REPORT)
